⟦vr:smooth_r⟧ = ndimage.gaussian_filter(rng.normal(0.0, 1.0, (64, 64)), 5.0)
⟦vr:smooth_c⟧ = ndimage.gaussian_filter(rng.normal(0.0, 1.0, (64, 64)), 5.0)
